#!/usr/bin/env python3
"""t2d/init.bin -> kernel/mct_t2_init.h (same record format, see gen_init_blob.py)."""
import os
root = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
blob = open(os.path.join(root, "t2d", "init.bin"), "rb").read()
lines = [", ".join(f"0x{b:02x}" for b in blob[i:i + 12]) for i in range(0, len(blob), 12)]
out = ("/* SPDX-License-Identifier: GPL-2.0-only */\n"
       "/* Generated by tools/gen_init_header.py from t2d/init.bin — do not edit.\n"
       " * Device init sequence of the MCT Trigger II (from the vendor driver's USB traffic).\n"
       " * Records: u8 ep | u8 flags (1=zero payload, 2=read reply) | le32 len | data | [le32 rdlen]\n */\n"
       "static const u8 mct_t2_init_seq[] = {\n\t" + ",\n\t".join(lines) + ",\n};\n")
open(os.path.join(root, "kernel", "mct_t2_init.h"), "w").write(out)
print(f"{len(blob)} bytes -> kernel/mct_t2_init.h")
